def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = grid[0][0]
    left_w = 0
    while left_w < w and grid[0][left_w] == frame:
        left_w += 1
    left = [row[:left_w] for row in grid]

    separators = [r for r, row in enumerate(left) if all(v == frame for v in row)]
    panels = []
    for a, b in zip(separators, separators[1:]):
        if b > a + 1:
            panels.append((a, b))

    # Extract each colored object on the right as its occupied-cell mask.
    objects = {}
    for r in range(h):
        for c in range(left_w, w):
            color = grid[r][c]
            if color:
                objects.setdefault(color, set()).add((r, c))
    masks = {}
    for color, cells in objects.items():
        r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
        masks[color] = [[(r, c) in cells for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]

    out = [row[:] for row in left]
    for a, b in panels:
        inner = [(r, c) for r in range(a + 1, b) for c in range(1, left_w - 1) if left[r][c] == 0]
        height, width = b - a - 1, left_w - 2
        panel_mask = [[left[r][c] == 0 for c in range(1, left_w - 1)] for r in range(a + 1, b)]
        match = None
        for color, mask in masks.items():
            if mask == panel_mask:
                match = color
                break
        if match is None:
            continue
        for r, c in inner:
            out[r][c] = match
    return out
